  const BONE_ENVELOPE: Record<string, number> = {"pelvis": 0.18354, "abdomen": 0.17388, "chest": 0.31122, "clavicle-l": 0.137592, "clavicle-r": 0.137592, "thigh-l": 0.06384, "shin-l": 0.04704, "foot-l": 0.12, "thigh-r": 0.06384, "shin-r": 0.04704, "foot-r": 0.12, "upper-arm-l": 0.05376, "forearm-l": 0.04368, "upper-arm-r": 0.05376, "forearm-r": 0.04368, "hand-l": 0.03696, "hand-r": 0.03696, "neck": 0.0924, "head": 0.204, "index-l-1": 0.009408, "index-l-2": 0.009408, "index-l-3": 0.009408, "index-r-1": 0.009408, "index-r-2": 0.009408, "index-r-3": 0.009408, "little-l-1": 0.008064, "little-l-2": 0.008064, "little-l-3": 0.008064, "little-r-1": 0.008064, "little-r-2": 0.008064, "little-r-3": 0.008064, "middle-l-1": 0.009744, "middle-l-2": 0.009744, "middle-l-3": 0.009744, "middle-r-1": 0.009744, "middle-r-2": 0.009744, "middle-r-3": 0.009744, "ring-l-1": 0.009072, "ring-l-2": 0.009072, "ring-l-3": 0.009072, "ring-r-1": 0.009072, "ring-r-2": 0.009072, "ring-r-3": 0.009072, "thumb-l-1": 0.010752, "thumb-l-2": 0.010752, "thumb-l-3": 0.010752, "thumb-r-1": 0.010752, "thumb-r-2": 0.010752, "thumb-r-3": 0.010752};
